```verilog
`timescale 1ns/1ps
module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg [7:0] d;
    wire [7:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;

    initial begin
        // Initialize clock
        clk = 0;
        d = 8'b00000000;

        // Test case 1: Check reset state
        #10;
        if (q !== 8'b00000000) begin
            $display("Error: Expected q = 00000000, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 2: Load data into D flip-flops
        d = 8'b10101010; // Test pattern
        #10; // Wait for clock edge
        if (q !== 8'b10101010) begin
            $display("Error: Expected q = 10101010, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 3: Change input and check output
        d = 8'b11110000; // New test pattern
        #10; // Wait for clock edge
        if (q !== 8'b11110000) begin
            $display("Error: Expected q = 11110000, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 4: Check with another pattern
        d = 8'b00001111; // Another test pattern
        #10; // Wait for clock edge
        if (q !== 8'b00001111) begin
            $display("Error: Expected q = 00001111, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 5: Check with all bits set
        d = 8'b11111111; // All bits set
        #10; // Wait for clock edge
        if (q !== 8'b11111111) begin
            $display("Error: Expected q = 11111111, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 6: Check with all bits cleared
        d = 8'b00000000; // All bits cleared
        #10; // Wait for clock edge
        if (q !== 8'b00000000) begin
            $display("Error: Expected q = 00000000, got q = %b", q);
            errors = errors + 1;
        end

        // Test case 7: Random pattern
        d = 8'b11001100; // Random pattern
        #10; // Wait for clock edge
        if (q !== 8'b11001100) begin
            $display("Error: Expected q = 11001100, got q = %b", q);
            errors = errors + 1;
        end

        // Finalize test results
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Clock generation
    always #5 clk = ~clk; // Generate clock with a period of 10 time units
endmodule
```

